import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    n = int(data[0])

    if n == 0:
        print(-1)
        return

    if n == 1:
        print(0)
        return

    arr = list(map(int, data[1:n+1]))

    position_to_indices = {}
    for i in range(n):
        val = arr[i]
        if val not in position_to_indices:
            position_to_indices[val] = []
        position_to_indices[val].append(i)

    visited = [False] * n
    jumps = [0] * n

    queue = deque()
    queue.append(0)
    visited[0] = True
    jumps[0] = 0

    while queue:
        i = queue.popleft()

        if i == n - 1:
            break

        jump_target = arr[i] - 1

        if 0 <= jump_target < n and not visited[jump_target]:
            visited[jump_target] = True
            jumps[jump_target] = jumps[i] + 1
            queue.append(jump_target)

        if arr[i] in position_to_indices:
            for idx in position_to_indices[arr[i]]:
                if not visited[idx]:
                    visited[idx] = True
                    jumps[idx] = jumps[i] + 1
                    queue.append(idx)
            position_to_indices[arr[i]] = []

    print(jumps[n-1] if visited[n-1] else -1)

if __name__ == "__main__":
    main()
